function jumlahMaks(arr) {
  let saatIni = arr[0], terbaik = arr[0];
  for (let i = 1; i < arr.length; i++) {
    saatIni = Math.max(arr[i], saatIni + arr[i]);
    terbaik = Math.max(terbaik, saatIni);
  }
  return terbaik;
}

